-- Texas property_catalog website + Google rating bulk upsert, keyed by Google Place ID.
-- Source: Property Intelligence property.official_website_url + property.google_rating
-- (San Antonio + Austin + Dallas-Fort Worth + Houston). Idempotent + recoverable.
-- Upserts website_url + google_rating ONLY; preserves existing non-null values via
-- COALESCE; never touches neighborhood, location, location_keywords or zip.
begin;
on conflict (place_id) do update set
  website_url   = COALESCE(EXCLUDED.website_url,   property_catalog.website_url),
  google_rating = COALESCE(EXCLUDED.google_rating, property_catalog.google_rating),
  updated_at    = now();
commit;
